srcDoc.js:
const COLS = [
  { headerName: '', field: '__check', checkboxSelection: true, headerCheckboxSelection: true, width: 48, pinned: 'left', sortable: false, filter: false, resizable: false, suppressMenu: true },
  { headerName: 'Code', field: 'code', width: 90 },
  { headerName: 'Name', field: 'name', width: 220 },
  { headerName: 'MTID', field: 'mtid', width: 110 },
  { headerName: 'Service', field: 'service', width: 110 },
  { headerName: 'Rate Criteria', field: 'rate_criteria', width: 220 },
  { headerName: 'Effective Date', field: 'effective_date', width: 130 },
  { headerName: 'Utility', field: 'utility', width: 200 },
  { headerName: 'KWH Range', field: 'kwh_range', width: 120 },
  { headerName: 'KW Range', field: 'kw_range', width: 120 },
  { headerName: 'Customer Count', field: 'customer_count', width: 140 }
];

function normalizeData(model) {
  return Array.isArray(model && model.rows) ? model.rows : [];
}

let gridApi = null;

function emitSelection() {
  if (!gridApi) return;
  const rows = gridApi.getSelectedRows();
  if (appsmith.updateModel) appsmith.updateModel({ selectedRows: rows });
}

function renderGrid(model) {
  const rowData = normalizeData(model);
  const gridOptions = {
    columnDefs: COLS,
    rowData,
    rowSelection: 'multiple',
    suppressRowClickSelection: false,
    pagination: true,
    paginationPageSize: 25,
    paginationPageSizeSelector: [10, 25, 50, 100],
    defaultColDef: {
      sortable: true,
      resizable: true,
      filter: true,
      minWidth: 80,
      menuTabs: ['generalMenuTab', 'filterMenuTab', 'columnsMenuTab']
    },
    animateRows: true,
    popupParent: document.body,
    getRowId: p => String(p.data.masterTariffId),
    onGridReady: params => { gridApi = params.api; },
    onSelectionChanged: emitSelection
  };
  const gridDiv = document.querySelector('#myGrid');
  if (!gridDiv) return;
  gridDiv.innerHTML = '';
  gridApi = agGrid.createGrid(gridDiv, gridOptions);
}

appsmith.onReady(() => {
  renderGrid(appsmith.model);
  appsmith.onModelChange(renderGrid);
});

